package com.company.skillplatform.bundle.application;
import com.company.skillplatform.audit.application.DownloadAuditService;import com.company.skillplatform.bundle.infrastructure.repository.SkillBundleRepository;import com.company.skillplatform.common.application.BusinessException;import com.company.skillplatform.storage.domain.ObjectStoragePort;import java.io.*;import org.springframework.core.io.ByteArrayResource;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class BundleDownloadService{private final SkillBundleRepository bundles;private final ObjectStoragePort storage;private final DownloadAuditService audit;public BundleDownloadService(SkillBundleRepository b,ObjectStoragePort s,DownloadAuditService a){bundles=b;storage=s;audit=a;}@PreAuthorize("hasAuthority('skill:download')")@Transactional(readOnly=true)public ResponseEntity<ByteArrayResource> download(Long id,Long userId){var b=bundles.findById(id).orElseThrow(()->new BusinessException("BUNDLE_NOT_FOUND","Bundle not found",HttpStatus.NOT_FOUND));if(!"AVAILABLE".equals(b.getStatus()))throw new BusinessException("BUNDLE_NOT_AVAILABLE","Bundle is not available",HttpStatus.NOT_FOUND);try(InputStream in=storage.get(b.getObjectKey())){byte[] bytes=in.readAllBytes();audit.record(userId,null,id,b.getObjectKey());return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).contentLength(bytes.length).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+b.getFileName()).body(new ByteArrayResource(bytes));}catch(IOException e){throw new BusinessException("BUNDLE_READ_FAILED","Unable to read bundle",HttpStatus.BAD_GATEWAY);}}}
